import type { Question } from '../../lib/types'
export const route53_cloudfront_questions: Question[] = [
  { id: 'd2-r53-001', domain: 2, topics: ['Route 53', 'failover routing'], type: 'single', stem: 'An application is deployed in us-east-1 (primary) and eu-west-1 (standby). Traffic should only go to eu-west-1 when the primary fails health checks. Which routing policy?', options: [{ id: 'A', text: 'Geolocation routing' }, { id: 'B', text: 'Weighted routing with weights 100/0' }, { id: 'C', text: 'Failover routing' }, { id: 'D', text: 'Latency-based routing' }], correct: ['C'], explanation: 'Route 53 failover routing: active-passive configuration. All traffic goes to the primary record. When the primary health check fails, Route 53 automatically routes to the secondary. Requires health checks on the primary record.', distractors: {
      B: 'Weighted 100/0 always sends to primary — no automatic failover based on health checks.',
      D: 'Latency routing sends to lowest-latency region — not specifically an active-passive failover mechanism.',
      A: 'Geolocation routing uses user location — not health-check-based failover.'
    } },
  { id: 'd2-r53-002', domain: 2, topics: ['Route 53', 'alias record', 'zone apex'], type: 'single', stem: 'A company hosts a website at the zone apex (example.com — not www) and needs to point it to an ALB. Standard CNAME cannot be used at the apex. What record type solves this?', options: [{ id: 'A', text: 'CNAME record pointing to the ALB DNS name' }, { id: 'B', text: 'AAAA record with the ALB IPv6 address' }, { id: 'C', text: 'Route 53 Alias record' }, { id: 'D', text: 'A record with the ALB IP address' }], correct: ['C'], explanation: 'CNAME records are prohibited at the zone apex by DNS standards. Route 53 Alias records solve this — they function like CNAMEs but can be used at the apex, targeting ALBs, CloudFront, S3, and more. Queries to AWS targets are free.', distractors: {
      A: 'CNAME at the zone apex violates RFC 1912 and causes resolution failures.',
      D: 'ALB IPs change dynamically as it scales — hardcoded A records break when IPs change.',
      B: 'AAAA records are for IPv6 static IPs — ALB manages its own IPs; Alias handles both A and AAAA.'
    } },
  { id: 'd2-r53-003', domain: 2, topics: ['Route 53', 'health check', 'string matching'], type: 'single', stem: 'Route 53 should mark an endpoint unhealthy if the HTTP response body contains the string "ERROR". The endpoint returns HTTP 200 even on errors. What health check configuration enables this?', options: [{ id: 'A', text: 'HTTP health check with string matching' }, { id: 'B', text: 'CloudWatch alarm-based health check' }, { id: 'C', text: 'TCP health check' }, { id: 'D', text: 'HTTP health check monitoring response code only' }], correct: ['A'], explanation: 'Route 53 HTTP/HTTPS health checks with string matching check the first 5,120 bytes of the response body. If the string is (or is not) found, the check fails. This detects application-level errors that return HTTP 200.', distractors: {
      D: 'HTTP code-only checks pass on any 2xx — an error response of 200 with ERROR body would not be caught.',
      B: 'CloudWatch alarm health checks use metric-based alarms — not response body content inspection.',
      C: 'TCP health checks verify connectivity only — no HTTP response body inspection.'
    } },
  { id: 'd2-r53-004', domain: 2, topics: ['Route 53', 'weighted routing', 'blue-green'], type: 'single', stem: 'A team is deploying a new application version and wants 10% of traffic to go to the new version while 90% stays on the old version. Which routing policy provides this?', options: [{ id: 'A', text: 'Latency-based routing' }, { id: 'B', text: 'Weighted routing' }, { id: 'C', text: 'Failover routing' }, { id: 'D', text: 'Multivalue answer routing' }], correct: ['B'], explanation: 'Weighted routing distributes traffic based on relative weights. Setting old=90, new=10 sends 10% to the new version. Gradually shift weight as confidence grows. Weights are relative (not percentages) but the ratio determines distribution.', distractors: {
      C: 'Failover routing is active-passive based on health — not proportional split for canary deploys.',
      A: 'Latency routing routes to the fastest endpoint — not for controlled percentage-based traffic splits.',
      D: 'Multivalue answer returns multiple IPs randomly — not a configurable percentage split.'
    } },
  { id: 'd2-r53-005', domain: 2, topics: ['CloudFront', 'cache behaviors'], type: 'single', stem: 'A CloudFront distribution serves both static assets (/images/*) and an API (/api/*). The API must never be cached. Static assets should cache for 24 hours. How is this configured?', options: [{ id: 'A', text: 'Create multiple cache behaviors' }, { id: 'B', text: 'Set a single cache policy to 0 seconds for all paths' }, { id: 'C', text: 'Use Lambda@Edge to set Cache-Control headers on every request per path pattern' }, { id: 'D', text: 'Disable CloudFront caching entirely and use it only as a proxy layer for all paths' }], correct: ['A'], explanation: 'CloudFront supports multiple cache behaviors per distribution. Each behavior matches a URL path pattern and has its own cache policy, origin, and TTL. The default behavior (*) catches unmatched paths.', distractors: {
      B: 'A single 0-TTL policy forwards all requests to origin — no caching benefit for static assets.',
      D: 'Disabling caching defeats the purpose of CloudFront for static content.',
      C: 'Lambda@Edge can set headers but cache behaviors natively handle per-path TTL without code.'
    } },
  { id: 'd2-r53-006', domain: 2, topics: ['CloudFront', 'OAC', 'S3 private origin'], type: 'single', stem: 'A CloudFront distribution serves files from a private S3 bucket. Only CloudFront should retrieve files — direct S3 access must be blocked. What configuration achieves this?', options: [{ id: 'A', text: 'Make S3 bucket public but add an IP-based bucket policy restricting to CloudFront IP ranges' }, { id: 'B', text: 'Enable S3 Transfer Acceleration on the private bucket for faster CloudFront retrieval' }, { id: 'C', text: 'Store files in a public S3 bucket and use CloudFront WAF to block direct S3 access by URL' }, { id: 'D', text: 'Origin Access Control (OAC)' }], correct: ['D'], explanation: 'OAC allows CloudFront to sign requests to S3 using SigV4. The S3 bucket policy grants access only to the CloudFront distribution via the OAC principal. The bucket remains fully private — no public access needed.', distractors: {
      A: 'CloudFront IP ranges change constantly — IP-based bucket policies are fragile and not recommended.',
      B: 'S3 Transfer Acceleration speeds direct uploads from users — not relevant to CloudFront origin access control.',
      C: 'WAF can inspect HTTP requests — it cannot block direct S3 API requests made outside CloudFront.'
    } },
  { id: 'd2-r53-007', domain: 2, topics: ['Route 53', 'geolocation routing'], type: 'single', stem: 'A company wants to serve a GDPR-compliant EU version of their website to all European users and a default version to everyone else. Which routing policy handles this?', options: [{ id: 'A', text: 'Geolocation routing' }, { id: 'B', text: 'Weighted routing' }, { id: 'C', text: 'IP-based routing' }, { id: 'D', text: 'Latency-based routing' }], correct: ['A'], explanation: 'Route 53 geolocation routing matches by user location. Create EU continent/country records routing to the GDPR endpoint, and a default record (catches all unmatched locations) for the standard version.', distractors: {
      D: 'Latency routing optimizes for performance — may send EU users to non-EU regions if latency is better.',
      B: 'Weighted routing distributes proportionally by percentage — not by geographic origin.',
      C: 'IP-based routing only covers IPs you explicitly configure — misses all unlisted EU residential IPs.'
    } },
  { id: 'd2-r53-008', domain: 2, topics: ['CloudFront', 'ACM', 'us-east-1'], type: 'single', stem: 'A company needs HTTPS on their CloudFront distribution using a custom domain. Which certificate service and region must be used?', options: [{ id: 'A', text: 'ACM certificate in the same region as the CloudFront origin server' }, { id: 'B', text: 'ACM certificate in us-east-1 (N. Virginia)' }, { id: 'C', text: 'IAM server certificate imported to any region for CloudFront use' }, { id: 'D', text: 'A self-signed certificate works for CloudFront custom domains if the viewer accepts it' }], correct: ['B'], explanation: 'CloudFront requires ACM certificates to be in us-east-1 regardless of where the origin is located. This is a frequently tested exam trap. The certificate covers the CloudFront distribution\'s custom domain names.', distractors: { A: 'Origin region is irrelevant for CloudFront certificate region — always us-east-1 for ACM.', C: 'IAM server certificates are legacy — ACM in us-east-1 is the recommended approach.', D: 'Self-signed certificates cause browser SSL errors — ACM provides publicly trusted certificates.' } },
  { id: 'd2-r53-009', domain: 2, topics: ['Route 53', 'private hosted zone'], type: 'single', stem: 'An application in a VPC needs internal DNS names (app.internal.example.com) that only resolve within the VPC, not on the public internet. How is this configured?', options: [{ id: 'A', text: 'VPC DHCP options pointing to a custom DNS server on-premises for private resolution' }, { id: 'B', text: 'Public hosted zone with a restrictive IAM policy' }, { id: 'C', text: 'Route 53 Private Hosted Zone associated with the VPC' }, { id: 'D', text: 'EC2 instance running BIND9 as a private DNS server in the VPC' }], correct: ['C'], explanation: 'Route 53 Private Hosted Zones provide DNS resolution only within associated VPCs. External DNS resolvers cannot query these records. Multiple VPCs can be associated with the same private zone for shared internal DNS.', distractors: {
      B: 'Public hosted zones are internet-resolvable — IAM policies control API calls, not DNS query access.',
      D: 'Self-managed BIND requires patching, HA configuration, and monitoring — Private Hosted Zones are fully managed.',
      A: 'On-premises DNS creates dependency on on-premises connectivity — Route 53 Private Hosted Zones are cloud-native.'
    } },
  { id: 'd2-r53-010', domain: 2, topics: ['CloudFront', 'Lambda@Edge', 'viewer request'], type: 'single', stem: 'A CloudFront distribution needs to inspect JWT tokens in request headers and block unauthorized requests. Where should the Lambda@Edge function run for maximum security?', options: [{ id: 'A', text: 'Viewer request' }, { id: 'B', text: 'Origin response' }, { id: 'C', text: 'Viewer response' }, { id: 'D', text: 'Origin request' }], correct: ['A'], explanation: 'Viewer request Lambda@Edge runs for every request at the CloudFront edge, before the cache check. This blocks unauthorized requests before they reach the cache or origin — even cached unauthorized responses cannot be served.', distractors: {
      D: 'Origin request only runs on cache misses — a cached unauthorized response would bypass the Lambda entirely.',
      C: 'Viewer response runs after content is already returned — unauthorized content has already been served.',
      B: 'Origin response runs after the origin processes the request — cannot prevent the unauthorized request from reaching origin.'
    } },
  { id: 'd2-r53-011', domain: 2, topics: ['Route 53', 'DNSSEC'], type: 'single', stem: 'A company wants to protect their Route 53 hosted zone from DNS cache poisoning attacks by enabling cryptographic signing of DNS records. What feature provides this?', options: [{ id: 'A', text: 'Route 53 health checks' }, { id: 'B', text: 'Route 53 DNSSEC signing' }, { id: 'C', text: 'AWS Shield Advanced' }, { id: 'D', text: 'Route 53 Resolver DNSSEC validation' }], correct: ['B'], explanation: 'Route 53 DNSSEC signing enables cryptographic signing of all records in a hosted zone using KMS keys. DNS resolvers that support DNSSEC can validate signatures, preventing cache poisoning and DNS hijacking attacks.', distractors: { A: 'Health checks monitor endpoint availability — not DNS record integrity.', C: 'Shield protects against DDoS including DNS flood attacks — not DNS spoofing of record content.', D: 'Resolver DNSSEC validation validates responses from other DNS servers — it does not sign your own zone\'s records.' } },
  { id: 'd2-r53-012', domain: 2, topics: ['CloudFront', 'price class', 'cost'], type: 'single', stem: 'A company wants to reduce CloudFront costs by limiting content delivery to edge locations in North America and Europe only. What CloudFront feature enables this geographic edge restriction?', options: [{ id: 'A', text: 'CloudFront price class' }, { id: 'B', text: 'CloudFront origin group with geographic failover between US and EU origins' }, { id: 'C', text: 'CloudFront geo restriction' }, { id: 'D', text: 'Route 53 geolocation routing' }], correct: ['A'], explanation: 'CloudFront price classes control which geographic regions\' edge locations serve the distribution. Price Class 100 (cheapest) uses only North America and Europe. Data transfer rates are lower in those regions, reducing cost.', distractors: {
      C: 'Geo restriction blocks users in specific countries from accessing content — it doesn\'t select which edge locations to use.',
      D: 'Route 53 geolocation routes DNS queries — doesn\'t limit which CloudFront edge locations serve requests.',
      B: 'Origin groups provide HA between origins — not edge location geographic selection.'
    } },
  { id: 'd2-r53-013', domain: 2, topics: ['Route 53', 'Resolver', 'outbound endpoint'], type: 'single', stem: 'EC2 instances in a VPC need to resolve on-premises DNS names (corp.example.com) managed by on-premises DNS servers. What Route 53 component enables this outbound DNS forwarding?', options: [{ id: 'A', text: 'Create a Route 53 public hosted zone for corp.example.com and manually add all on-premises records' }, { id: 'B', text: 'Set VPC DHCP options to on-premises DNS servers for all DNS queries including AWS service endpoints' }, { id: 'C', text: 'Install DNS proxy software on an EC2 instance in the VPC to forward to on-premises DNS' }, { id: 'D', text: 'Route 53 Resolver outbound endpoint' }], correct: ['D'], explanation: 'Route 53 Resolver outbound endpoints forward specific DNS queries (by domain name via forwarding rules) to on-premises DNS servers over Direct Connect or VPN. Only specified domains are forwarded — AWS service DNS continues normally.', distractors: {
      A: 'Public hosted zones are internet-resolvable and require manual record management — not a live forwarding mechanism.',
      B: 'Pointing all DNS to on-premises breaks AWS service resolution (S3, RDS, etc.) and creates dependency.',
      C: 'Self-managed DNS proxy requires maintenance — Route 53 Resolver is the managed solution.'
    } },
  { id: 'd2-r53-014', domain: 2, topics: ['CloudFront', 'WAF', 'us-east-1'], type: 'single', stem: 'A company wants to attach an AWS WAF Web ACL to their CloudFront distribution to block SQL injection attempts. In which region must the Web ACL be created?', options: [{ id: 'A', text: 'us-east-1 (N. Virginia)' }, { id: 'B', text: 'CloudFront has a dedicated WAF region' }, { id: 'C', text: 'Any region' }, { id: 'D', text: 'Same region as the origin' }], correct: ['A'], explanation: 'CloudFront WAF Web ACLs must be in us-east-1, the same requirement as CloudFront ACM certificates. Regional WAF Web ACLs (for ALB, API Gateway, AppSync) can be in any region.', distractors: {
      D: 'Origin region is irrelevant — CloudFront WAF must always be in us-east-1.',
      C: 'WAF is not automatically global — the Web ACL must be explicitly created in us-east-1 for CloudFront use.',
      B: 'CloudFront distributions are global — WAF for CloudFront is fixed to us-east-1 regardless of any "distribution region".'
    } },
  { id: 'd2-r53-015', domain: 2, topics: ['Route 53', 'latency routing'], type: 'single', stem: 'An application is deployed in us-east-1, eu-west-1, and ap-southeast-1. Users should be automatically routed to the region with the lowest network latency. Which routing policy?', options: [{ id: 'A', text: 'Geoproximity routing' }, { id: 'B', text: 'Latency-based routing' }, { id: 'C', text: 'Geolocation routing' }, { id: 'D', text: 'Weighted routing with equal weights' }], correct: ['B'], explanation: 'Route 53 latency-based routing uses AWS\'s empirical latency measurements to route users to the lowest-latency region. It measures actual network latency from different client locations to each AWS region — not just geographic proximity.', distractors: {
      C: 'Geolocation routes by country/continent — a UK user always goes to EU regardless of whether us-east-1 is faster.',
      A: 'Geoproximity routes based on calculated geographic distance with optional bias — not based on measured latency.',
      D: 'Equal weighted routing distributes randomly — ignores latency differences.'
    } },
  { id: 'd2-r53-016', domain: 2, topics: ['CloudFront', 'signed URLs', 'signed cookies'], type: 'single', stem: 'A video streaming service needs to restrict access so only authenticated users can play premium content through CloudFront. What CloudFront feature enables user-level access control?', options: [{ id: 'A', text: 'CloudFront signed URLs (per file) or signed cookies (multiple files)' }, { id: 'B', text: 'Lambda@Edge basic auth' }, { id: 'C', text: 'CloudFront geo restriction' }, { id: 'D', text: 'S3 bucket policy restriction' }], correct: ['A'], explanation: 'CloudFront signed URLs control access to individual objects. Signed cookies control access to multiple objects (e.g., entire video library). Both use RSA key pairs to create time-limited, user-specific access tokens checked by CloudFront.', distractors: {
      C: 'Geo restriction blocks entire countries — not per-user authentication for individual premium accounts.',
      D: 'S3 bucket policies control direct S3 access — OAC is used alongside signed URLs for CloudFront-served private content.',
      B: 'Lambda@Edge basic auth is a custom implementation — signed URLs/cookies are CloudFront\'s native access control.'
    } },
  { id: 'd2-r53-017', domain: 2, topics: ['Route 53', 'multivalue answer'], type: 'single', stem: 'A company runs 6 web servers and wants Route 53 to return multiple healthy IP addresses per DNS query for simple client-side load balancing. Which routing policy returns multiple IPs with health checking?', options: [{ id: 'A', text: 'Weighted routing with equal weights' }, { id: 'B', text: 'Simple routing with multiple values' }, { id: 'C', text: 'Latency routing' }, { id: 'D', text: 'Multivalue answer routing' }], correct: ['D'], explanation: 'Multivalue answer routing returns up to 8 randomly selected healthy IPs per DNS query. Clients receive multiple IPs and can retry others if one fails. Health checks are evaluated before including a record — unhealthy records are excluded.', distractors: {
      A: 'Weighted routing returns one record at a time proportional to weights — not multiple IPs per query.',
      C: 'Latency routing returns the single lowest-latency endpoint only — not multiple IPs.',
      B: 'Simple routing with multiple values returns all values including unhealthy ones — multivalue checks health.'
    } },
  { id: 'd2-r53-018', domain: 2, topics: ['CloudFront', 'custom error pages'], type: 'single', stem: 'When an S3 origin returns a 403 error, CloudFront should display a custom maintenance HTML page instead of the raw S3 error response. How is this configured?', options: [{ id: 'A', text: 'Lambda@Edge origin response function' }, { id: 'B', text: 'Create a separate S3 bucket containing error pages and configure as a second origin for error paths' }, { id: 'C', text: 'CloudFront custom error responses' }, { id: 'D', text: 'Modify the S3 error document setting' }], correct: ['C'], explanation: 'CloudFront custom error responses map origin HTTP error codes (403, 404, 500, etc.) to custom HTML pages stored in the distribution. The custom page is served with a configurable cache TTL instead of the raw origin error.', distractors: {
      D: 'S3 error documents apply to static website hosting direct access — not to requests via CloudFront with OAC.',
      A: 'Lambda@Edge works but is more complex — CloudFront custom error responses are a native configuration feature.',
      B: 'Separate error origin adds routing complexity — custom error responses are native to CloudFront behavior.'
    } },
  { id: 'd2-r53-019', domain: 2, topics: ['Route 53', 'geoproximity', 'Traffic Flow'], type: 'single', stem: 'A global company wants to route users in Atlantic regions toward their us-east-1 endpoint by expanding its geographic coverage area. Which Route 53 feature supports adjusting geographic coverage with a "bias" parameter?', options: [{ id: 'A', text: 'Weighted routing' }, { id: 'B', text: 'Geoproximity routing with bias' }, { id: 'C', text: 'Geolocation routing' }, { id: 'D', text: 'IP-based routing' }], correct: ['B'], explanation: 'Route 53 geoproximity routing routes based on geographic proximity. A positive bias expands the area served by that endpoint; negative bias shrinks it. Useful for shifting traffic boundaries between regions. Requires Route 53 Traffic Flow.', distractors: {
      C: 'Geolocation routes by exact country/continent definitions — no bias parameter for boundary adjustment.',
      A: 'Weighted routing controls proportional distribution — not geographic area boundaries.',
      D: 'IP-based routing maps explicit CIDR blocks — no geographic bias expansion concept.'
    } },
  { id: 'd2-r53-020', domain: 2, topics: ['CloudFront', 'field-level encryption'], type: 'single', stem: 'A CloudFront distribution processes credit card numbers in POST forms. The card number must remain encrypted through CloudFront and intermediate processing, readable only by the final application server. What feature provides this?', options: [{ id: 'A', text: 'CloudFront HTTPS' }, { id: 'B', text: 'KMS envelope encryption at the origin' }, { id: 'C', text: 'S3 SSE-KMS on the bucket storing card data' }, { id: 'D', text: 'CloudFront field-level encryption' }], correct: ['D'], explanation: 'CloudFront field-level encryption encrypts specific POST form fields at the CloudFront edge using a public key. Only the application server with the corresponding private key can decrypt the field — intermediate services and CloudFront cannot read it.', distractors: {
      A: 'TLS terminates at CloudFront — data is decrypted at the edge. Field-level encryption provides payload-level protection within the HTTPS tunnel.',
      B: 'KMS at origin encrypts after CloudFront already delivered plaintext — the intermediate path is unprotected.',
      C: 'S3 SSE-KMS protects stored data — not the credit card number in transit during form processing.'
    } },
  { id: 'd2-r53-021', domain: 2, topics: ['Route 53', 'TTL', 'DNS migration'], type: 'single', stem: 'A company is planning a DNS migration from an old IP to a new IP next week. What should be done BEFORE the migration day to ensure fast cutover and rollback capability?', options: [{ id: 'A', text: 'Lower the TTL to 60 seconds several days before' }, { id: 'B', text: 'Delete the old DNS record the day before migration to pre-stage the cutover' }, { id: 'C', text: 'Set weighted routing 50/50 between old and new IPs starting two days before migration' }, { id: 'D', text: 'Increase the TTL to 86400 (24 hours) to reduce DNS query volume before migration' }], correct: ['A'], explanation: 'Lower TTL days in advance so clients stop caching the old value for long. When you update the DNS record during migration, clients pick up the new IP within 60 seconds. If rollback is needed, the revert also propagates within 60 seconds.', distractors: {
      D: 'Higher TTL means clients cache the old value for 24 hours after you change it — extremely slow propagation.',
      B: 'Deleting the record causes an outage during the gap between deletion and new record propagation.',
      C: 'A 50/50 split sends half of traffic to the broken new IP before it\'s ready — not a valid pre-migration step.'
    } },
  { id: 'd2-r53-022', domain: 2, topics: ['CloudFront', 'origin groups', 'failover'], type: 'single', stem: 'A CloudFront distribution has a primary S3 origin and a backup S3 origin in another region. If the primary returns 5xx errors, CloudFront should automatically retry the backup. How is this configured?', options: [{ id: 'A', text: 'Create two separate CloudFront distributions and use Route 53 failover routing between them' }, { id: 'B', text: 'Configure an origin group with primary and secondary origins and set 5xx status codes as failover criteria' }, { id: 'C', text: 'Lambda@Edge origin request function' }, { id: 'D', text: 'CloudFront standard logging' }], correct: ['B'], explanation: 'CloudFront origin groups support automatic failover. Define primary and secondary origins in a group. Configure which HTTP status codes (e.g., 503, 504) trigger failover. On those errors, CloudFront automatically retries the secondary origin.', distractors: { A: 'Separate distributions require external DNS-level failover — origin groups handle automatic within-CloudFront failover.', C: 'Lambda@Edge works for complex failover logic — origin groups provide native failover without any code.', D: 'Standard logging records events after the fact — not a real-time failover mechanism.' } },
  { id: 'd2-r53-023', domain: 2, topics: ['Route 53', 'health check', 'CloudWatch', 'private resource'], type: 'single', stem: 'A Route 53 health check must monitor an application in a private subnet with no internet-facing endpoint. Route 53 health checkers are internet-based. What is the solution?', options: [{ id: 'A', text: 'Create a CloudWatch alarm monitoring the private application, then configure Route 53 to monitor the alarm state' }, { id: 'B', text: 'Route 53 can access private resources using a VPC endpoint for the health check service' }, { id: 'C', text: 'Route 53 cannot health check private resources' }, { id: 'D', text: 'Assign a public IP to the private instance specifically for Route 53 health check access' }], correct: ['A'], explanation: 'Route 53 health checkers run on the public internet and cannot reach private resources. The workaround: publish internal metrics to CloudWatch, create a CloudWatch alarm, configure Route 53 to monitor the alarm state (healthy/unhealthy).', distractors: {
      B: 'Route 53 health checkers do not use VPC endpoints — they are internet-based health check agents.',
      D: 'Adding a public IP defeats the purpose of private subnet architecture and creates a security risk.',
      C: 'Monitoring via CloudWatch alarm state is a supported mechanism — Route 53 can health check private resources this way.'
    } },
  { id: 'd2-r53-024', domain: 2, topics: ['CloudFront', 'cache key', 'query strings'], type: 'single', stem: 'A CloudFront distribution caches API responses. The API uses ?lang=en and ?lang=fr to serve different content. CloudFront ignores the query string and serves the same cached response regardless of lang. Fix?', options: [{ id: 'A', text: 'The API is incorrectly implementing language detection' }, { id: 'B', text: 'Enable HTTPS on the distribution' }, { id: 'C', text: 'CloudFront does not support query strings' }, { id: 'D', text: 'Configure the cache policy to include the lang query string parameter in the cache key' }], correct: ['D'], explanation: 'CloudFront by default ignores query strings in the cache key. Configure the cache policy to include specific query strings (like "lang") — CloudFront then caches ?lang=en and ?lang=fr separately, serving the correct language content.', distractors: {
      C: 'CloudFront fully supports query strings — it ignores them for cache key by default but this is configurable.',
      A: 'The problem description states different content per language exists — the issue is CloudFront cache key configuration.',
      B: 'HTTPS vs HTTP doesn\'t affect query string handling in CloudFront cache keys.'
    } },
  { id: 'd2-r53-025', domain: 2, topics: ['Route 53', 'nameserver delegation', 'third-party registrar'], type: 'single', stem: 'A company purchased a domain through a third-party registrar and wants Route 53 for DNS without transferring domain registration. How?', options: [{ id: 'A', text: 'Route 53 only manages DNS for domains registered through Route 53' }, { id: 'B', text: 'Use Route 53 Resolver instead' }, { id: 'C', text: 'Create a Route 53 public hosted zone and update the domain nameservers at the third-party registrar to Route 53 NS records' }, { id: 'D', text: 'Transfer the domain to Route 53 Registrar' }], correct: ['C'], explanation: 'Route 53 hosted zones work independently of domain registration. Create a public hosted zone in Route 53, then update the nameserver (NS) records at the third-party registrar to the four NS values from the Route 53 hosted zone.', distractors: {
      D: 'Domain transfer is optional — Route 53 DNS works for any domain by delegating NS records to Route 53.',
      A: 'Route 53 DNS management works for any domain — registration and DNS are independent concerns.',
      B: 'Route 53 Resolver handles hybrid DNS (VPC to on-premises) — not public DNS for third-party registered domains.'
    } },
  { id: 'd2-r53-026', domain: 2, topics: ['CloudFront', 'real-time logs', 'Kinesis'], type: 'single', stem: 'A security team needs CloudFront request logs in near real-time (within 1 second) for anomaly detection. Standard S3 logs have multi-minute delays. What CloudFront feature provides this?', options: [{ id: 'A', text: 'CloudFront standard logging to S3' }, { id: 'B', text: 'CloudFront real-time logs delivered to Kinesis Data Streams' }, { id: 'C', text: 'CloudWatch Logs for CloudFront access events' }, { id: 'D', text: 'CloudTrail for CloudFront' }], correct: ['B'], explanation: 'CloudFront real-time logs deliver log records to a Kinesis Data Stream within 1 second of the viewer request. This enables real-time analytics, anomaly detection, and monitoring pipelines using Kinesis consumers.', distractors: { A: 'Standard logging writes to S3 with multi-minute delays — it does not deliver within 1 second.', C: 'CloudFront does not natively send access logs to CloudWatch Logs — CloudWatch captures aggregate metrics, not per-request logs.', D: 'CloudTrail captures CloudFront API calls (configuration changes) — not viewer request access logs.' } },
  { id: 'd2-r53-027', domain: 2, topics: ['Route 53', 'Traffic Flow'], type: 'single', stem: 'A company needs a Route 53 routing policy combining latency-based routing with failover to a backup region and wants to visually design and version the configuration. What feature provides this?', options: [{ id: 'A', text: 'Route 53 Traffic Flow' }, { id: 'B', text: 'CloudFront routing rules' }, { id: 'C', text: 'Create individual routing policy records and manually chain them by referencing health checks' }, { id: 'D', text: 'Route 53 Resolver' }], correct: ['A'], explanation: 'Route 53 Traffic Flow provides a visual policy editor for creating complex routing configurations that combine multiple types (latency, failover, weighted, geolocation). Policies can be versioned, rolled back, and applied to multiple records.', distractors: {
      C: 'Manual records can be combined but Traffic Flow makes complex combinations manageable with versioning.',
      D: 'Route 53 Resolver handles hybrid DNS resolution — not complex public routing policy design.',
      B: 'CloudFront routing is for cache behaviors and origins — not Route 53 DNS routing policy design.'
    } },
  { id: 'd2-r53-028', domain: 2, topics: ['CloudFront', 'cache invalidation'], type: 'single', stem: 'A team deployed a new JavaScript app to S3 but CloudFront still serves the old cached version. How is the cache cleared immediately?', options: [{ id: 'A', text: 'Delete and recreate the CloudFront distribution to flush all cached objects simultaneously' }, { id: 'B', text: 'Change the S3 bucket name' }, { id: 'C', text: 'Wait for the current TTL to expire' }, { id: 'D', text: 'Create a CloudFront invalidation for the updated paths (/app.js or /*)' }], correct: ['D'], explanation: 'CloudFront invalidations remove specific cached objects from edge locations before TTL expires. Use specific paths (/app.js) or wildcards (/*). First 1,000 paths per month are free; additional paths incur a charge.', distractors: {
      C: 'Waiting for TTL works eventually — invalidation provides immediate refresh without waiting.',
      A: 'Recreating the distribution loses all configuration and requires DNS updates — invalidation is the correct tool.',
      B: 'Changing the S3 bucket name breaks the entire distribution origin — invalidation targets specific cached objects.'
    } },
  { id: 'd2-r53-029', domain: 2, topics: ['Route 53', 'CNAME', 'A record'], type: 'single', stem: 'A company\'s application load balancer changes its IP addresses frequently. What DNS record type avoids manual IP updates?', options: [{ id: 'A', text: 'CNAME record pointing to the ALB DNS name' }, { id: 'B', text: 'SRV record' }, { id: 'C', text: 'MX record' }, { id: 'D', text: 'A record with the current IP' }], correct: ['A'], explanation: 'A CNAME record points to a hostname rather than an IP. When the ALB changes IPs, only the ALB\'s A record changes — all CNAMEs pointing to the ALB hostname automatically resolve to the new IP without any updates.', distractors: {
      D: 'A records bind to a specific IP — require manual updates when the ALB\'s IP changes.',
      C: 'MX records are for mail exchange routing — not web application or load balancer addressing.',
      B: 'SRV records specify service host and port — typically for VoIP or game servers, not general web apps.'
    } },
  { id: 'd2-r53-030', domain: 2, topics: ['CloudFront', 'cache hit ratio', 'optimization'], type: 'single', stem: 'A CloudFront distribution has a low cache hit ratio (20%). Most requests hit the origin. The cache key includes all headers, cookies, and query strings. What fix improves cache efficiency?', options: [{ id: 'A', text: 'Remove unnecessary headers, cookies, and query strings from the cache key' }, { id: 'B', text: 'Switch to a cheaper CloudFront price class' }, { id: 'C', text: 'Add more edge locations to the distribution' }, { id: 'D', text: 'Decrease TTL' }], correct: ['A'], explanation: 'A low hit ratio means the cache key has too much variability — every slightly different request is a cache miss. Include only the headers/cookies/query strings that affect content differentiation in the cache key.', distractors: {
      C: 'More edge locations distribute the same hit count — they don\'t change the hit ratio.',
      D: 'Lower TTL means objects expire sooner — the hit ratio decreases further.',
      B: 'Price class affects geographic edge coverage — not the per-object cache hit rate.'
    } },
  { id: 'd2-r53-031', domain: 2, topics: ['Route 53', 'split-horizon DNS'], type: 'single', stem: 'An application should resolve to internal IPs for corporate VPC users and to external IPs for public internet users, using the same domain name. How is this configured in Route 53?', options: [{ id: 'A', text: 'Create two separate domains' }, { id: 'B', text: 'Configure DHCP options for the VPC with a custom DNS server that returns internal IPs per host' }, { id: 'C', text: 'Route 53 weighted routing between internal and external record sets for proportional traffic splits' }, { id: 'D', text: 'Split-horizon DNS' }], correct: ['D'], explanation: 'Split-horizon DNS: create both a public and a private hosted zone for the same domain. VPC users (with private zone associated) resolve to internal IPs; external internet users resolve through the public zone to external IPs.', distractors: {
      A: 'Different domain names defeat the purpose — split-view serves the same domain to different populations.',
      C: 'Weighted routing splits traffic proportionally — not based on whether the user is internal or external.',
      B: 'DHCP custom DNS requires running your own DNS servers — split-horizon via Route 53 zones is the managed solution.'
    } },
  { id: 'd2-r53-032', domain: 2, topics: ['CloudFront', 'CloudFront Functions'], type: 'single', stem: 'A team needs lightweight URL rewriting at CloudFront edges. Execution time is under 1ms and code is simple JavaScript. CloudFront Functions vs Lambda@Edge — which is better?', options: [{ id: 'A', text: 'API Gateway' }, { id: 'B', text: 'ALB routing rules' }, { id: 'C', text: 'CloudFront Functions' }, { id: 'D', text: 'Lambda@Edge' }], correct: ['C'], explanation: 'CloudFront Functions run JavaScript in microseconds (vs Lambda@Edge milliseconds) at ~6x lower cost. They handle lightweight operations at viewer request/response events: URL rewrites, header manipulation, A/B testing redirects.', distractors: {
      D: 'Lambda@Edge supports full Node.js/Python and complex logic but costs more and has higher latency — overkill for simple URL rewrites.',
      A: 'API Gateway is an origin — it processes requests at the origin region, not at CloudFront edges.',
      B: 'ALB processes traffic at the origin region — not at CloudFront edge locations globally.'
    } },
  { id: 'd2-r53-033', domain: 2, topics: ['Route 53', 'domain transfer lock'], type: 'single', stem: 'A domain registered with Route 53 Registrar must be protected against unauthorized transfer to another registrar. What security feature prevents this?', options: [{ id: 'A', text: 'Route 53 DNSSEC signing' }, { id: 'B', text: 'Domain transfer lock (Registrar Lock)' }, { id: 'C', text: 'Route 53 hosted zone deletion protection' }, { id: 'D', text: 'AWS Shield Advanced' }], correct: ['B'], explanation: 'The Registrar Lock prevents domain transfers to another registrar. The domain owner must explicitly disable the lock before a transfer can proceed. Route 53-registered domains have transfer lock enabled by default.', distractors: {
      C: 'Hosted zone deletion protection prevents accidental DNS zone deletion — not domain registrar transfer.',
      A: 'DNSSEC prevents DNS spoofing by signing records — does not stop registrar-level domain transfers.',
      D: 'Shield protects against DDoS attacks — not unauthorized domain transfer at the registrar level.'
    } },
  { id: 'd2-r53-034', domain: 2, topics: ['CloudFront', 'WebSocket support'], type: 'single', stem: 'A real-time chat application uses WebSocket connections. The frontend is behind CloudFront. Does CloudFront support WebSocket, and is any special configuration required?', options: [{ id: 'A', text: 'Yes' }, { id: 'B', text: 'No' }, { id: 'C', text: 'Yes, but only when HTTP/2 is enabled' }, { id: 'D', text: 'Yes, but only when Lambda@Edge is configured to handle the WebSocket upgrade protocol' }], correct: ['A'], explanation: 'CloudFront natively supports the WebSocket protocol. WebSocket upgrade (HTTP → WS) requests are transparently proxied through CloudFront to the origin. No special cache behaviors, Lambda@Edge, or other configuration is needed.', distractors: {
      B: 'WebSocket works through CloudFront without any bypass or special routing.',
      D: 'Lambda@Edge is not required for WebSocket — CloudFront handles the upgrade automatically.',
      C: 'WebSocket works with both HTTP/1.1 (standard upgrade) and HTTP/2 through CloudFront.'
    } },
  { id: 'd2-r53-035', domain: 2, topics: ['Route 53', 'IP-based routing'], type: 'single', stem: 'A company wants to route corporate office traffic from specific IP ranges to a dedicated backend and all other traffic to a general backend. Which routing policy maps CIDR blocks to specific records?', options: [{ id: 'A', text: 'Geolocation routing' }, { id: 'B', text: 'Geoproximity routing' }, { id: 'C', text: 'Weighted routing' }, { id: 'D', text: 'IP-based routing' }], correct: ['D'], explanation: 'Route 53 IP-based routing (GA 2023) maps client IP CIDR blocks to specific endpoints. Create CIDR collections and associate them with routing records. Corporate office CIDRs route to dedicated backend; all others get the default record.', distractors: {
      A: 'Geolocation routes by country/continent — doesn\'t match specific corporate IP ranges across countries.',
      C: 'Weighted routing distributes proportionally — no CIDR-based source routing capability.',
      B: 'Geoproximity routes by geographic distance — cannot be configured to match specific IP CIDR ranges.'
    } },
  { id: 'd2-r53-036', domain: 2, topics: ['CloudFront', 'Continuous Deployment'], type: 'single', stem: 'A team wants to test a new CloudFront configuration on 5% of production traffic before fully rolling it out. What built-in CloudFront feature supports this?', options: [{ id: 'A', text: 'CloudFront Continuous Deployment' }, { id: 'B', text: 'Route 53 weighted routing to two separate CloudFront distributions for percentage-based testing' }, { id: 'C', text: 'Lambda@Edge A/B testing' }, { id: 'D', text: 'CloudFront weighted routing between two distributions' }], correct: ['A'], explanation: 'CloudFront Continuous Deployment allows creating a staging distribution with a new configuration and routing a percentage (or header-based) of production traffic to it. After validation, promote the staging config to production in one click.', distractors: {
      D: 'CloudFront does not have its own weighted routing — Route 53 has weighted routing.',
      B: 'Route 53 weighted routing works but is external to CloudFront — Continuous Deployment is built natively into CloudFront.',
      C: 'Lambda@Edge can implement A/B testing but Continuous Deployment is the native CloudFront feature for configuration testing.'
    } },
  { id: 'd2-r53-037', domain: 2, topics: ['Route 53', 'NS record', 'SOA record'], type: 'single', stem: 'When a new public hosted zone is created in Route 53, which records are automatically created by Route 53?', options: [{ id: 'A', text: 'A record and CNAME record' }, { id: 'B', text: 'MX record and TXT record' }, { id: 'C', text: 'NS (Name Server) and SOA (Start of Authority) records' }, { id: 'D', text: 'AAAA and CAA records' }], correct: ['C'], explanation: 'Route 53 automatically creates NS and SOA records for every new public hosted zone. NS records list the four Route 53 nameservers for the zone. SOA contains administrative information. All other records must be created manually.', distractors: {
      A: 'A and CNAME records must be created manually — Route 53 doesn\'t know which IPs or hostnames to point to.',
      B: 'MX and TXT records must be created manually for email and domain verification.',
      D: 'AAAA and CAA records require explicit creation — they are not auto-created.'
    } },
  { id: 'd2-r53-038', domain: 2, topics: ['CloudFront', 'standard logging', 'S3'], type: 'single', stem: 'A security team needs to audit all CloudFront viewer requests including client IPs, URIs, user agents, and response codes for compliance. What CloudFront feature provides this per-request detail?', options: [{ id: 'A', text: 'CloudFront standard access logs' }, { id: 'B', text: 'CloudWatch metrics' }, { id: 'C', text: 'AWS Config' }, { id: 'D', text: 'VPC Flow Logs' }], correct: ['A'], explanation: 'CloudFront standard access logs record every request: client IP, user agent, request URI, response code, bytes, referrer, and more. Logs are delivered to a specified S3 bucket in gzip format, typically within a few minutes.', distractors: {
      B: 'CloudWatch metrics provide aggregate statistics (total requests, error rate, latency) — not per-request details needed for compliance.',
      D: 'VPC Flow Logs capture EC2/VPC network traffic — CloudFront is a global edge network outside VPC scope.',
      C: 'AWS Config tracks resource configuration state — not CloudFront viewer request access logs.'
    } },
  { id: 'd2-r53-039', domain: 2, topics: ['Route 53', 'Resolver inbound endpoint'], type: 'single', stem: 'On-premises servers need to resolve private DNS names (RDS endpoint hostnames) from a Route 53 private hosted zone. What Route 53 component enables on-premises DNS resolution of AWS private zones?', options: [{ id: 'A', text: 'Route 53 public hosted zone with the same domain' }, { id: 'B', text: 'Direct Connect BGP routing' }, { id: 'C', text: 'Route 53 Resolver outbound endpoint' }, { id: 'D', text: 'Route 53 Resolver inbound endpoint' }], correct: ['D'], explanation: 'Route 53 Resolver inbound endpoints provide IPs in your VPC that on-premises DNS servers can forward queries to. On-premises DNS → forwarding rule sends AWS domain queries → inbound endpoint → resolves private hosted zone records.', distractors: {
      C: 'Outbound endpoints forward queries FROM the VPC TO on-premises — the opposite of what\'s needed here.',
      A: 'Public hosted zones are internet-resolvable — this would expose private AWS records publicly, which is a security risk.',
      B: 'Direct Connect BGP routes IP traffic — not DNS resolver IP advertisement.'
    } },
  { id: 'd2-r53-040', domain: 2, topics: ['CloudFront', 'viewer protocol policy'], type: 'single', stem: 'A CloudFront distribution should redirect all HTTP requests to HTTPS automatically. Where in CloudFront is this configured?', options: [{ id: 'A', text: 'Configure HTTP→HTTPS redirect in the origin S3 static website hosting settings' }, { id: 'B', text: 'Set viewer protocol policy to "Redirect HTTP to HTTPS" in the CloudFront cache behavior settings' }, { id: 'C', text: 'Use Lambda@Edge viewer request function' }, { id: 'D', text: 'Configure an ALB listener rule to redirect HTTP to HTTPS at the load balancer origin' }], correct: ['B'], explanation: 'The CloudFront viewer protocol policy on each cache behavior controls how HTTP/HTTPS requests are handled. "Redirect HTTP to HTTPS" returns a 301 for HTTP requests, transparently upgrading clients to HTTPS at the edge.', distractors: { A: 'S3 static website redirect options only apply to direct S3 access — not requests routed through CloudFront with OAC.', C: 'Lambda@Edge works but is unnecessary overhead — native viewer protocol policy handles this with zero code.', D: 'ALB listener rules work at the origin region — CloudFront viewer protocol policy handles the redirect at the edge before reaching origin.' } },
  { id: 'd2-r53-041', domain: 2, topics: ['Route 53', 'fast health checks'], type: 'single', stem: 'Route 53 health checks are not detecting failures quickly enough. Current detection time is 90+ seconds. What change reduces time-to-detect to approximately 30 seconds?', options: [{ id: 'A', text: 'Set health check interval to 10 seconds (fast health check)' }, { id: 'B', text: 'Switch from HTTP to TCP health check' }, { id: 'C', text: 'Increase the failure threshold from 3 to 1' }, { id: 'D', text: 'Add more Route 53 health check regions' }], correct: ['A'], explanation: 'Fast health checks run every 10 seconds. Standard interval is 30 seconds. With a threshold of 3 failures, fast health checks detect failures in approximately 30 seconds (3 × 10s) vs 90+ seconds for standard interval checks.', distractors: {
      C: 'Threshold 1 means a single failure marks unhealthy — increases false positives from transient failures.',
      D: 'More regions improve check accuracy and resilience — they don\'t change the interval between checks.',
      B: 'TCP checks verify port connectivity — the interval (30s vs 10s) determines detection speed, not check protocol type.'
    } },
  { id: 'd2-r53-042', domain: 2, topics: ['CloudFront', 'Origin Shield'], type: 'single', stem: 'Cache misses from CloudFront edge locations worldwide are all going directly to the origin, causing high origin load. A centralized caching layer between edges and origin would reduce this. What is this feature?', options: [{ id: 'A', text: 'Configure multiple origins' }, { id: 'B', text: 'Enable Origin Access Control' }, { id: 'C', text: 'Increase CloudFront TTL' }, { id: 'D', text: 'CloudFront Origin Shield' }], correct: ['D'], explanation: 'CloudFront Origin Shield is an additional caching layer in a single AWS region between all global edge locations and the origin. Cache misses from edges check Origin Shield first before going to the origin — reduces origin load by up to 90%.', distractors: {
      C: 'Higher TTL reduces per-edge miss frequency but doesn\'t add a centralized cache tier between all edges and origin.',
      A: 'Multiple origins add redundancy but don\'t reduce total request volume — each origin still receives miss traffic.',
      B: 'OAC controls who can access S3 — not a caching layer that reduces origin request volume.'
    } },
  { id: 'd2-r53-043', domain: 2, topics: ['Route 53', 'latency routing', 'exam trap'], type: 'single', stem: 'Route 53 latency-based routing has endpoints in us-east-1 and eu-west-1. A user in London makes a request. Is it guaranteed they will always be routed to eu-west-1?', options: [{ id: 'A', text: 'Not necessarily' }, { id: 'B', text: 'Yes, because London is geographically in Europe and latency to eu-west-1 is always lower' }, { id: 'C', text: 'Latency routing uses geolocation data, not actual measurements' }, { id: 'D', text: 'Yes' }], correct: ['A'], explanation: 'Latency routing is based on empirical latency measurements, not just geographic proximity. While EU users typically get better latency to eu-west-1, network conditions vary. Route 53 uses historical data — us-east-1 could occasionally have lower measured latency.', distractors: {
      D: 'Geographic proximity and measured latency are correlated but not identical — network path quality matters.',
      C: 'Latency routing uses actual latency measurements — the behavior described is geolocation routing, not latency routing.',
      B: 'Geographically closer and lower-latency are usually the same — but not always. This conflates geolocation with latency routing.'
    } },
  { id: 'd2-r53-044', domain: 2, topics: ['CloudFront', 'CORS', 'cache key'], type: 'single', stem: 'A React app on CloudFront at app.example.com calls an API at api.example.com. CORS preflight requests (OPTIONS) are returning wrong CORS headers because CloudFront ignores the Origin header in the cache key. Fix?', options: [{ id: 'A', text: 'Disable CloudFront caching entirely' }, { id: 'B', text: 'Move the API to the same domain as the React app' }, { id: 'C', text: 'Configure the cache policy to include the Origin and Access-Control-Request-* headers in the cache key for CORS requests' }, { id: 'D', text: 'Switch to HTTP instead of HTTPS' }], correct: ['C'], explanation: 'CloudFront must include the Origin header (and Access-Control-Request-Headers, Access-Control-Request-Method) in the cache key so different CORS origins get separately cached responses with the correct CORS headers.', distractors: {
      A: 'Disabling caching eliminates CloudFront\'s performance benefit — including CORS headers in the cache key is the targeted fix.',
      B: 'Same-domain hosting eliminates CORS but requires major architecture changes — cache key configuration is the direct solution.',
      D: 'HTTPS vs HTTP does not affect CORS policy or how CloudFront handles CORS header caching.'
    } },
  { id: 'd2-r53-045', domain: 2, topics: ['Route 53', 'domain registration', 'hosted zone auto-creation'], type: 'single', stem: 'A company registers a new domain through Route 53 Registrar. Which AWS resource is automatically created during the registration process?', options: [{ id: 'A', text: 'A Route 53 public hosted zone' }, { id: 'B', text: 'An S3 bucket named after the domain' }, { id: 'C', text: 'A CloudFront distribution with the domain as a CNAME' }, { id: 'D', text: 'An ACM certificate for the domain' }], correct: ['A'], explanation: 'When a domain is registered through Route 53 Registrar, a public hosted zone is automatically created. The NS records in the hosted zone are set as the domain\'s nameservers at the registrar. NS and SOA records are pre-configured.', distractors: {
      C: 'CloudFront distributions must be created manually — they are not auto-provisioned on domain registration.',
      D: 'ACM certificate issuance requires an explicit request — not automatically created.',
      B: 'S3 buckets are not automatically created on domain registration — they must be created separately.'
    } },
]
